params.command:
$ErrorActionPreference='Stop'
$repo='C:\Users\Xxkan\local-ai-workspaces\mhw-mods'
Set-Location $repo
git fetch origin --prune
$branches=@(
'agent/bridge-uia-hardening-20260929',
'agent/bridge-uia-native-20260929',
'agent/control-test-narrow-test-scope-only-build-a-r-20260928133350-vrokm',
'agent/launch-observation-atomicity-20260928',
'agent/swarm-contract-v3-20260929-0540',
'agent-bridge',
'codex/complete-mod-workflows',
'fix/codex-quota-dispatch-circuit-20260929'
)
$worktrees=@{}
$p=$null
foreach($line in @(git worktree list --porcelain)){
 if($line -like 'worktree *'){$p=$line.Substring(9)}
 elseif($line -like 'branch refs/heads/*' -and $p){$worktrees[$line.Substring(18)]=$p}
 elseif([string]::IsNullOrWhiteSpace($line)){$p=$null}
}
$out=@()
foreach($b in $branches){
 git show-ref --verify --quiet ("refs/remotes/origin/"+$b)
 if($LASTEXITCODE -ne 0){$out += [pscustomobject]@{branch=$b;state='missing'};continue}
 $tip=(git rev-parse ("origin/"+$b)).Trim()
 $counts=(git rev-list --left-right --count ("origin/main...origin/"+$b)).Trim() -split '\s+'
 $cherry=@(git cherry origin/main ("origin/"+$b))
 $plus=@($cherry|Where-Object{$_ -like '+ *'})
 $minus=@($cherry|Where-Object{$_ -like '- *'})
 $subjects=@()
 foreach($line in $plus){$sha=($line -split '\s+')[1];$subjects+=(git show -s --format='%H|%s' $sha).Trim()}
 $out += [pscustomobject]@{
   branch=$b;tip=$tip;behind=[int]$counts[0];ahead=[int]$counts[1];
   patch_unique_count=$plus.Count;patch_equivalent_count=$minus.Count;
   patch_unique_commits=$subjects;
   worktree=if($worktrees.ContainsKey($b)){$worktrees[$b]}else{$null}
 }
}
[pscustomobject]@{main=(git rev-parse origin/main).Trim();branches=$out} | ConvertTo-Json -Depth 6
